\node[hdr, minimum width=\colB, right=0pt of h1] (h2) {Annual (\$)};
\node[hdr, minimum width=\colC, right=0pt of h2] (h3) {Expenses};
\node[hdr, minimum width=\colD, right=0pt of h3] (h4) {Annual (\$)};
