\node[cell, minimum width=\colB, right=0pt of c1] (c2) {};
\node[cell, minimum width=\colC, right=0pt of c2] (c3) {Transport};
\node[cell, minimum width=\colD, right=0pt of c3] (c4) {\$4500};
\node[cell, minimum width=\colA, below=0pt of c1.south west, anchor=north west] (d1) {};
\node[cell, minimum width=\colB, right=0pt of d1] (d2) {};
\node[cell, minimum width=\colC, right=0pt of d2] (d3) {Utilities};
